const workflowStaticData = $getWorkflowStaticData('global');

// Agent creation response
const agentId = $input.first().json.id;
const agentLink = $input.first().json.call_link;

// CX Feedback preparation node
const satisfactionDescription = $('Prepare TruGen Feedback Intelligence Agent')
  .first()
  .json
  .trugenCustomerSatisfactionDescription;

const agentName = $('Prepare TruGen Feedback Intelligence Agent').first().json.agentName;
const systemPrompt = $('Prepare TruGen Feedback Intelligence Agent').first().json.systemPrompt;
const welcomeMessage = $('Prepare TruGen Feedback Intelligence Agent').first().json.welcomeMessage;

// Store globally for downstream sentiment / CSAT workflows
workflowStaticData.agentId = agentId;
workflowStaticData.trugenCustomerSatisfactionDescription = satisfactionDescription;
workflowStaticData.agentLink = agentLink;

return [{
  json: {
    "Agent ID": workflowStaticData.agentId,
    "Agent Name": agentName,
    "Agent Link": workflowStaticData.agentLink,
    "CX Description": workflowStaticData.trugenCustomerSatisfactionDescription,
    "System Prompt": systemPrompt,
    "Welcome Message": welcomeMessage,
    "Agent Purpose": "Customer Satisfaction & Call Sentiment Analysis"
  }
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "sentiment": {
      "type": "string",
      "enum": ["Positive", "Negative", "Neutral", "Mixed"],
      "description": "Overall sentiment of the conversation based only on user statements."
    },
    "csat_score": {
      "type": "number",
      "minimum": 1,
      "maximum": 5,
      "description": "Customer Satisfaction Score from 1 to 5, where 5 is highly satisfied."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Confidence level of the analysis from 0 to 1."
    },
    "user_conversation_summary": {
      "type": "string",
      "description": "Concise summary of only the user's statements and feedback during the conversation."
    },
    "key_insights": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "3–5 actionable insights derived from the user's feedback."
    },
    "pain_points": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Problems, frustrations, or concerns expressed by the user."
    },
    "positive_aspects": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Positive feedback or satisfaction indicators mentioned by the user."
    },
    "resolution_status": {
      "type": "string",
      "enum": ["Resolved", "Pending", "Escalated", "Unresolved"],
      "description": "Current status of the user's issue, if any."
    },
    "emotion_detected": {
      "type": "string",
      "description": "Primary emotion detected from the user's tone (e.g., Satisfaction, Frustration, Neutral, Confidence)."
    }
  },
  "required": [
    "sentiment",
    "csat_score",
    "confidence",
    "user_conversation_summary",
    "resolution_status",
    "emotion_detected"
  ],
  "additionalProperties": false,
  "$schema": "http://json-schema.org/draft-07/schema#"
}
